//! OAuth 2.1 authentication for MCP servers.//!//! Implements the MCP Authorization specification using OAuth 2.1 with PKCE.//! See: https://spec.modelcontextprotocol.io/specification/2025-03-26/basic/authorization/use std::collections::HashMap;use std::net::IpAddr;use std::sync::Arc;use std::time::Duration;use base64::{Engine, engine::general_purpose::URL_SAFE_NO_PAD};use rand::RngCore;use serde::{Deserialize, Serialize};use sha2::{Digest, Sha256};use tokio::net::TcpListener;use crate::cli::oauth_defaults::{self, OAUTH_CALLBACK_PORT};use crate::secrets::{CreateSecretParams, SecretsStore};use crate::tools::mcp::config::McpServerConfig;/// Shared HTTP client for all OAuth/discovery requests.////// Redirects are disabled for security (prevents redirect-based SSRF)./// Per-request timeouts can override the default via `.timeout()` on/// the request builder.fn oauth_http_client() -> Result<&'static reqwest::Client, AuthError> {    static CLIENT: std::sync::OnceLock<Result<reqwest::Client, AuthError>> =        std::sync::OnceLock::new();    CLIENT        .get_or_init(|| {            reqwest::Client::builder()                .timeout(Duration::from_secs(30))                .redirect(reqwest::redirect::Policy::none())                .build()                .map_err(|e| AuthError::Http(e.to_string()))        })        .as_ref()        .map_err(Clone::clone)}/// Log a debug message when a discovery/auth response is a redirect./// Helps users diagnose configuration issues when legitimate servers/// redirect and our no-redirect policy causes a failure.fn log_redirect_if_applicable(url: &str, response: &reqwest::Response) {    if response.status().is_redirection() {        let location = response            .headers()            .get("location")            .and_then(|v| v.to_str().ok());        tracing::debug!(            "OAuth request to '{}' returned redirect {} -> {:?} (redirects disabled for security)",            url,            response.status(),            location        );    }}/// OAuth authorization error.#[derive(Debug, Clone, thiserror::Error)]pub enum AuthError {    #[error("Server does not support OAuth authorization")]    NotSupported,    #[error("Failed to discover authorization endpoints: {0}")]    DiscoveryFailed(String),    #[error("Authorization denied by user")]    AuthorizationDenied,    #[error("Token exchange failed: {0}")]    TokenExchangeFailed(String),    #[error("Token expired and refresh failed: {0}")]    RefreshFailed(String),    #[error("No access token available")]    NoToken,    #[error("Timeout waiting for authorization callback")]    Timeout,    #[error("Could not bind to callback port")]    PortUnavailable,    #[error("HTTP error: {0}")]    Http(String),    #[error("Secrets error: {0}")]    Secrets(String),}/// OAuth protected resource metadata./// Discovered from /.well-known/oauth-protected-resource.#[derive(Debug, Clone, Serialize, Deserialize)]pub struct ProtectedResourceMetadata {    /// The protected resource identifier.    pub resource: String,    /// Authorization servers that can issue tokens for this resource.    #[serde(default)]    pub authorization_servers: Vec<String>,    /// Scopes supported by this resource.    #[serde(default)]    pub scopes_supported: Vec<String>,}/// OAuth authorization server metadata./// Discovered from /.well-known/oauth-authorization-server.#[derive(Debug, Clone, Serialize, Deserialize)]pub struct AuthorizationServerMetadata {    /// Authorization server issuer.    pub issuer: String,    /// Authorization endpoint URL.    pub authorization_endpoint: String,    /// Token endpoint URL.    pub token_endpoint: String,    /// Dynamic client registration endpoint (if DCR is supported).    #[serde(default)]    pub registration_endpoint: Option<String>,    /// Supported response types.    #[serde(default)]    pub response_types_supported: Vec<String>,    /// Supported grant types.    #[serde(default)]    pub grant_types_supported: Vec<String>,    /// Supported code challenge methods.    #[serde(default)]    pub code_challenge_methods_supported: Vec<String>,    /// Scopes supported by this server.    #[serde(default)]    pub scopes_supported: Vec<String>,}/// Dynamic Client Registration request.#[derive(Debug, Clone, Serialize)]pub struct ClientRegistrationRequest {    /// Human-readable client name.    pub client_name: String,    /// Redirect URIs for OAuth callbacks.    pub redirect_uris: Vec<String>,    /// Grant types the client will use.    pub grant_types: Vec<String>,    /// Response types the client will use.    pub response_types: Vec<String>,    /// Token endpoint authentication method.    pub token_endpoint_auth_method: String,}/// Dynamic Client Registration response.#[derive(Debug, Clone, Deserialize)]pub struct ClientRegistrationResponse {    /// The assigned client ID.    pub client_id: String,    /// Client secret (if issued).    #[serde(default)]    pub client_secret: Option<String>,    /// When the client secret expires (if applicable).    #[serde(default)]    pub client_secret_expires_at: Option<u64>,    /// Registration access token for managing the registration.    #[serde(default)]    pub registration_access_token: Option<String>,    /// Registration client URI for managing the registration.    #[serde(default)]    pub registration_client_uri: Option<String>,}/// Access token with optional refresh token and expiry.#[derive(Debug, Clone)]pub struct AccessToken {    /// The access token value.    pub access_token: String,    /// Token type (usually "Bearer").    pub token_type: String,    /// Seconds until expiration (if provided).    pub expires_in: Option<u64>,    /// Refresh token for obtaining new access tokens.    pub refresh_token: Option<String>,    /// Scopes granted.    pub scope: Option<String>,}/// Token response from the authorization server.#[derive(Debug, Deserialize)]struct TokenResponse {    access_token: String,    token_type: String,    expires_in: Option<u64>,    refresh_token: Option<String>,    scope: Option<String>,}/// PKCE verifier and challenge pair.#[derive(Debug, Clone)]pub struct PkceChallenge {    /// Code verifier (high-entropy random string).    pub verifier: String,    /// Code challenge (S256 hash of verifier).    pub challenge: String,}impl PkceChallenge {    /// Generate a new PKCE challenge pair.    pub fn generate() -> Self {        let mut verifier_bytes = [0u8; 32];        rand::rngs::OsRng.fill_bytes(&mut verifier_bytes);        let verifier = URL_SAFE_NO_PAD.encode(verifier_bytes);        let mut hasher = Sha256::new();        hasher.update(verifier.as_bytes());        let challenge = URL_SAFE_NO_PAD.encode(hasher.finalize());        Self {            verifier,            challenge,        }    }}// ---------------------------------------------------------------------------// Well-known URI construction (RFC 8414 / RFC 9728)// ---------------------------------------------------------------------------/// Build a well-known URI according to RFC 8414 / RFC 9728.////// The path component of the base URL is placed *after* the well-known suffix:/// ```text/// https://example.com/path + oauth-authorization-server///   -> https://example.com/.well-known/oauth-authorization-server/path/// ```pub fn build_well_known_uri(base_url: &str, suffix: &str) -> Result<String, AuthError> {    let parsed = reqwest::Url::parse(base_url)        .map_err(|e| AuthError::DiscoveryFailed(format!("Invalid URL: {}", e)))?;    let origin = parsed.origin().ascii_serialization();    let path = parsed.path().trim_end_matches('/');    Ok(format!("{}/.well-known/{}{}", origin, suffix, path))}// ---------------------------------------------------------------------------// RFC 8707 resource parameter// ---------------------------------------------------------------------------/// Compute the canonical resource URI for RFC 8707.////// Strips fragments and trailing slashes from the server URL.pub fn canonical_resource_uri(server_url: &str) -> String {    match reqwest::Url::parse(server_url) {        Ok(mut parsed) => {            parsed.set_fragment(None);            let s = parsed.to_string();            s.trim_end_matches('/').to_string()        }        Err(_) => server_url.trim_end_matches('/').to_string(),    }}// ---------------------------------------------------------------------------// SSRF protection// ---------------------------------------------------------------------------/// Check if an IP address is dangerous (loopback, link-local, private, etc.)fn is_dangerous_ip(ip: IpAddr) -> bool {    match ip {        IpAddr::V4(v4) => {            v4.is_loopback()                || v4.is_private()                || v4.is_link_local()                || v4.is_broadcast()                || v4.is_unspecified()                || (v4.octets()[0] == 169 && v4.octets()[1] == 254) // link-local                || (v4.octets()[0] == 100 && (v4.octets()[1] & 0xC0) == 64) // CGNAT 100.64/10        }        IpAddr::V6(v6) => {            let segs = v6.segments();            v6.is_loopback()                || v6.is_unspecified()                // Link-local (fe80::/10)                || (segs[0] & 0xffc0) == 0xfe80                // Site-local / deprecated (fec0::/10)                || (segs[0] & 0xffc0) == 0xfec0                // Unique local (fc00::/7)                || (segs[0] & 0xfe00) == 0xfc00                // Documentation (2001:db8::/32)                || (segs[0] == 0x2001 && segs[1] == 0x0db8)                // Check for IPv4-mapped IPv6 (::ffff:x.x.x.x)                || v6                    .to_ipv4_mapped()                    .is_some_and(|v4| is_dangerous_ip(IpAddr::V4(v4)))        }    }}/// Validate that a URL is safe for server-side requests (SSRF protection).async fn validate_url_safe(url: &str) -> Result<(), AuthError> {    let parsed = reqwest::Url::parse(url)        .map_err(|e| AuthError::DiscoveryFailed(format!("Invalid URL: {}", e)))?;    // Must be HTTPS. HTTP is only allowed for localhost/loopback (dev scenarios).    let scheme = parsed.scheme();    if scheme != "https" && scheme != "http" {        return Err(AuthError::DiscoveryFailed(format!(            "Unsupported scheme: {}",            scheme        )));    }    if scheme == "http" {        if !crate::tools::mcp::config::is_localhost_url(url) {            let host = parsed.host_str().unwrap_or("");            return Err(AuthError::DiscoveryFailed(format!(                "HTTP is only allowed for localhost; use HTTPS for '{}'",                host            )));        }        // Localhost HTTP is allowed for dev — skip SSRF checks since we've        // already validated the host is localhost/loopback.        return Ok(());    }    let host = parsed        .host_str()        .ok_or_else(|| AuthError::DiscoveryFailed("URL has no host".to_string()))?;    // For IP literals, parse directly and check.    if let Ok(ip) = host.parse::<IpAddr>()        && is_dangerous_ip(ip)    {        return Err(AuthError::DiscoveryFailed(format!(            "URL points to a restricted IP address: {}",            host        )));    }    // For hostnames, resolve DNS and check each resolved address.    // This prevents DNS-based SSRF where a hostname resolves to an internal IP    // (e.g., 169.254.169.254 for cloud metadata endpoints).    if host.parse::<IpAddr>().is_err() {        let addr = format!("{}:{}", host, parsed.port_or_known_default().unwrap_or(443));        match tokio::net::lookup_host(&addr).await {            Ok(addrs) => {                for socket_addr in addrs {                    if is_dangerous_ip(socket_addr.ip()) {                        return Err(AuthError::DiscoveryFailed(format!(                            "URL hostname '{}' resolves to restricted IP address: {}",                            host,                            socket_addr.ip()                        )));                    }                }            }            Err(e) => {                // DNS failure = fail closed (do not allow the request)                return Err(AuthError::DiscoveryFailed(format!(                    "DNS resolution failed for '{}': {}",                    host, e                )));            }        }    }    Ok(())}// ---------------------------------------------------------------------------// Multi-strategy OAuth discovery helpers// ---------------------------------------------------------------------------/// Parse the resource_metadata URL from a WWW-Authenticate header value.fn parse_resource_metadata_url(www_authenticate: &str) -> Option<String> {    // Try comma-separated parameters first    for part in www_authenticate.split(',') {        let part = part.trim();        if let Some(rest) = part.strip_prefix("resource_metadata=\"") {            return rest.strip_suffix('"').map(|s| s.to_string());        }        if let Some(rest) = part.strip_prefix("resource_metadata=") {            let val = rest.trim_matches('"');            return Some(val.to_string());        }    }    // Also try whitespace-separated tokens (e.g. Bearer resource_metadata="url")    for part in www_authenticate.split_whitespace() {        if let Some(rest) = part.strip_prefix("resource_metadata=\"") {            return rest                .trim_end_matches(',')                .strip_suffix('"')                .map(|s| s.to_string());        }        if let Some(rest) = part.strip_prefix("resource_metadata=") {            let val = rest.trim_matches('"').trim_end_matches(',');            return Some(val.to_string());        }    }    None}/// Fetch protected resource metadata from a URL.async fn fetch_resource_metadata(url: &str) -> Result<ProtectedResourceMetadata, AuthError> {    validate_url_safe(url).await?;    let client = oauth_http_client()?;    let response = client        .get(url)        .timeout(Duration::from_secs(10))        .send()        .await        .map_err(|e| AuthError::DiscoveryFailed(e.to_string()))?;    log_redirect_if_applicable(url, &response);    if !response.status().is_success() {        return Err(AuthError::DiscoveryFailed(format!(            "HTTP {}",            response.status()        )));    }    response        .json()        .await        .map_err(|e| AuthError::DiscoveryFailed(format!("Invalid metadata: {}", e)))}/// Try to discover OAuth metadata via 401 challenge response.////// Also accepts 400 responses, since some servers return 400 for/// unauthenticated requests.  In practice the 400 path rarely yields a/// `WWW-Authenticate` header (GitHub's MCP does not), so discovery/// typically falls through to strategy 2 (RFC 9728) or 3 (direct).async fn discover_via_401(server_url: &str) -> Result<AuthorizationServerMetadata, AuthError> {    validate_url_safe(server_url).await?;    let client = oauth_http_client()?;    let response = client        .post(server_url)        .timeout(Duration::from_secs(10))        .header("Content-Type", "application/json")        .body("{}")        .send()        .await        .map_err(|e| AuthError::DiscoveryFailed(e.to_string()))?;    log_redirect_if_applicable(server_url, &response);    let status = response.status().as_u16();    // Accept 401 (standard) and 400 (some servers like GitHub MCP use this).    // In both cases, look for WWW-Authenticate header with discovery metadata.    if status != 401 && status != 400 {        return Err(AuthError::DiscoveryFailed(format!(            "Expected 401 or 400, got {}",            response.status()        )));    }    let www_auth = response        .headers()        .get("WWW-Authenticate")        .and_then(|v| v.to_str().ok())        .ok_or_else(|| {            AuthError::DiscoveryFailed(format!("No WWW-Authenticate header in {} response", status))        })?;    let resource_metadata_url = parse_resource_metadata_url(www_auth).ok_or_else(|| {        AuthError::DiscoveryFailed(            "No resource_metadata URL in WWW-Authenticate header".to_string(),        )    })?;    let resource_meta = fetch_resource_metadata(&resource_metadata_url).await?;    try_discover_from_auth_servers(&resource_meta).await}/// Try to discover auth server metadata from resource metadata's authorization_servers list.